(()=>{
  "use strict";
  const EXPEDITIONS={
    water:{name:"Freshwater Lake",icon:"💧",terrain:"Lake shore",reward:"7 water units",className:"lake",description:"Collect clean garden water from a freshwater lake on Earth.",lesson:"Freshwater lakes collect rain, stream water and groundwater. Water taken for plants must be stored safely and used carefully."},
    garden:{name:"Garden Loam",icon:"🌱",terrain:"Temperate garden",reward:"3 loam packs",className:"loam",description:"Collect dark, crumbly loam for tomatoes and peas.",lesson:"Loam contains a useful mixture of sand, silt, clay and organic matter. Its pores hold water while still allowing air around roots."},
    sandy:{name:"Sandy Soil",icon:"🏜️",terrain:"River sandbank",reward:"3 sandy-soil packs",className:"sand",description:"Collect loose, well-drained soil for carrots and sunflowers.",lesson:"Large sand particles leave wide pore spaces. Water drains quickly, and roots can push through the loose soil more easily."},
    red:{name:"Red Earth",icon:"🟥",terrain:"Tropical upland",reward:"3 red-soil packs",className:"red",description:"Collect iron-rich red earth for future tropical crops.",lesson:"Many red soils contain iron oxides. Colour alone does not show fertility, so scientists also test drainage, pH and nutrients."}
  };
  const QUESTIONS=[
    {q:"Which Earth location is the approved source of garden water?",a:["A freshwater lake","A dry crater","A fuel tank"],right:0,hint:"Look for a natural body of fresh water.",why:"The expedition collects water only at the freshwater lake."},
    {q:"Why can loam support many garden plants?",a:["It balances water-holding and drainage","It contains no pore spaces","It is made only of metal"],right:0,hint:"Roots need both water and air.",why:"Mixed particle sizes help loam hold water while leaving spaces for air."},
    {q:"Which soil is easiest for a carrot root to push through?",a:["Loose sandy soil","Solid rock","Compacted clay"],right:0,hint:"A swollen root needs room to lengthen.",why:"Loose sandy soil offers less resistance to a growing taproot."},
    {q:"What makes many tropical soils look red?",a:["Iron oxides","Blue plastic","Frozen salt"],right:0,hint:"Think about iron changing colour when it reacts with oxygen.",why:"Iron oxides often give soil a red or orange colour."},
    {q:"What do plant roots need in soil besides water?",a:["Air and mineral nutrients","Only darkness","Paint and glass"],right:0,hint:"Living root cells respire and absorb dissolved substances.",why:"Roots use oxygen and absorb water containing mineral nutrients."},
    {q:"What happens when soil drains well?",a:["Extra water can move through pore spaces","All roots disappear","The soil becomes a lake"],right:0,hint:"Drainage describes water movement.",why:"Connected pore spaces allow extra water to move downward."},
    {q:"Why should water be collected only after a science check?",a:["To connect the resource with safe evidence","To make the lake vanish","To stop every plant growing"],right:0,hint:"The expedition is also a learning mission.",why:"The science check makes resource collection part of the lesson."},
    {q:"Which material can improve garden loam?",a:["Decomposed organic matter","Broken glass","Plastic wrappers"],right:0,hint:"Think about compost.",why:"Decomposed organic matter can add nutrients and improve soil structure."},
    {q:"Which soil normally drains fastest?",a:["Soil with many large sand particles","Waterlogged compact clay","Solid bedrock"],right:0,hint:"Large particles leave larger spaces.",why:"Large sand particles create pore spaces through which water moves quickly."},
    {q:"Why test red soil instead of judging only by colour?",a:["Colour does not reveal every soil property","Every red soil is identical","Colour measures rainfall"],right:0,hint:"Scientists use more than one observation.",why:"Drainage, nutrients and pH can differ even when soils look similar."},
    {q:"What carries dissolved minerals from soil into a plant?",a:["Water absorbed by roots","Sunlight alone","Dry air outside leaves"],right:0,hint:"Minerals dissolve before moving into roots.",why:"Water dissolves mineral ions and helps transport them into root tissues."},
    {q:"Which statement describes freshwater?",a:["It contains much less dissolved salt than seawater","It is always frozen","It contains no matter"],right:0,hint:"Compare a lake with the ocean.",why:"Freshwater has a much lower salt concentration than seawater."}
  ];
  const GEMS=[
    ["Ruby Courage","#ff4b50",0,"Recovery"],["Sapphire Insight","#4da7ff",1,"Observation"],["Emerald Growth","#45e58d",2,"Life"],["Amethyst Memory","#a97aff",3,"Memory"],["Amber Charge","#ffc34f",4,"Energy"],["Aquamarine Flow","#49e6f2",5,"Water"],["Opal Discovery","#ffd2ef",6,"Discovery"],["Smoky Quartz Shield","#b88d72",7,"Protection"]
  ];
  let active=null;
  const shuffle=list=>{const result=[...list];for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]]}return result};
  const esc=value=>String(value??"").replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]));
  function ensure(state){state.garden=state.garden||{};state.garden.soils={garden:Number(state.garden.soils?.garden)||0,sandy:Number(state.garden.soils?.sandy)||0,red:Number(state.garden.soils?.red)||0};state.garden.resourceRuns=Number(state.garden.resourceRuns)||0;return state.garden}
  function awardGem(game){
    if(Math.random()>=.18)return null;
    const [name,color,sprite,trait]=GEMS[Math.floor(Math.random()*GEMS.length)],gem={id:`field-gem-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,name,color,sprite,trait,effect:`A rare ${trait.toLowerCase()} resonance discovered during Earth fieldwork.`,forgedAt:Date.now(),usedBy:"",origin:"Earth terrain discovery"};
    game.state.gemWorkshop.forged.push(gem);return gem;
  }
  function award(game){const garden=ensure(game.state),kind=game.kind;if(kind==="water")garden.water=(Number(garden.water)||0)+7;else garden.soils[kind]=(garden.soils[kind]||0)+3;garden.resourceRuns++;game.gem=awardGem(game);game.complete=true;game.save();render(game)}
  function choose(game,kind){game.kind=kind;game.deck=shuffle(QUESTIONS).slice(0,5).map(question=>{const choices=shuffle(question.a.map((text,index)=>({text,correct:index===question.right})));return{...question,choices}});game.index=0;game.correct=0;game.feedback="";game.hint=false;game.complete=false;game.gem=null;render(game)}
  function answer(game,index){const q=game.deck[game.index],choice=q.choices[index];if(!choice)return;if(choice.correct){game.correct++;game.feedback=`Correct! ${q.why}`;game.locked=true;setTimeout(()=>{if(active!==game)return;if(game.correct>=5)award(game);else{game.index++;game.feedback="";game.hint=false;game.locked=false;render(game)}},650)}else{game.feedback=`Try again. ${q.why}`;game.hint=true}render(game)}
  function renderHome(game){const garden=ensure(game.state);game.root.innerHTML=`<section class="earth-resource-screen"><header class="resource-header"><button id="resourceBack">← Garden</button><div><p>PLANET EARTH · FIELD SUPPLY MISSIONS</p><h1>Choose a terrain</h1><span>Water and soil can only be collected at the matching Earth location. Every trip requires 5 correct Science answers.</span></div></header><div class="resource-inventory"><span>💧 Water <b>${garden.water||0}</b></span><span>🌱 Loam <b>${garden.soils.garden}</b></span><span>🏜️ Sandy <b>${garden.soils.sandy}</b></span><span>🟥 Red earth <b>${garden.soils.red}</b></span></div><main class="resource-terrain-grid">${Object.entries(EXPEDITIONS).map(([id,item])=>`<button class="resource-terrain ${item.className}" data-expedition="${id}"><span>${item.icon}</span><small>${esc(item.terrain)}</small><h2>${esc(item.name)}</h2><p>${esc(item.description)}</p><b>5 Science checks · ${esc(item.reward)} →</b></button>`).join("")}</main><aside class="resource-rule"><strong>RESOURCE RULE</strong><p>Seeds are not sold here. Existing plants return seeds at harvest; new species are discovered as hidden drops while reading Science lessons.</p></aside></section>`;document.getElementById("resourceBack").onclick=game.onExit;document.querySelectorAll("[data-expedition]").forEach(button=>button.onclick=()=>choose(game,button.dataset.expedition))}
  function renderQuiz(game){const item=EXPEDITIONS[game.kind],q=game.deck[game.index];game.root.innerHTML=`<section class="earth-resource-screen quiz ${item.className}"><header class="resource-header"><button id="resourceBack">← Terrains</button><div><p>${esc(item.terrain.toUpperCase())} · SCIENCE CHECK ${game.correct+1}/5</p><h1>${item.icon} ${esc(item.name)}</h1><span>${esc(item.lesson)}</span></div><div class="resource-quiz-score"><b>${game.correct}/5</b><small>correct</small></div></header><main class="resource-quiz-card"><div class="resource-scene"><i></i><span>${item.icon}</span><strong>${esc(item.terrain)}</strong></div><article><small>QUESTION ${game.index+1} / 5</small><h2>${esc(q.q)}</h2><div class="resource-answers">${q.choices.map((choice,index)=>`<button data-resource-answer="${index}" ${game.locked?"disabled":""}><span>${String.fromCharCode(65+index)}</span>${esc(choice.text)}</button>`).join("")}</div><p class="resource-feedback ${game.feedback.startsWith("Correct")?"good":""}">${esc(game.feedback)}</p><button class="resource-hint" id="resourceHint">${game.hint?esc(q.hint):"Need help? Show hint"}</button></article></main></section>`;document.getElementById("resourceBack").onclick=()=>{game.kind="";render(game)};document.querySelectorAll("[data-resource-answer]").forEach(button=>button.onclick=()=>answer(game,Number(button.dataset.resourceAnswer)));document.getElementById("resourceHint").onclick=()=>{game.hint=true;render(game)}}
  function renderComplete(game){const item=EXPEDITIONS[game.kind];game.root.innerHTML=`<section class="earth-resource-screen complete ${item.className}"><div class="resource-complete-card"><div class="resource-reward-icon">${item.icon}</div><p>EARTH EXPEDITION COMPLETE</p><h1>${esc(item.reward)} collected</h1><p>${esc(item.lesson)}</p>${game.gem?`<div class="field-gem-drop"><span class="gem-sprite gem-${game.gem.sprite}"></span><div><b>RARE GEM DROP!</b><strong>${esc(game.gem.name)}</strong><small>Sent directly to the Storage Chest.</small></div></div>`:`<div class="no-gem-drop">No gem signal this trip. Rare drops can appear on a future expedition.</div>`}<div><button id="resourceAgain">Visit another terrain</button><button id="resourceDone">Return to Garden</button></div></div></section>`;document.getElementById("resourceAgain").onclick=()=>{game.kind="";render(game)};document.getElementById("resourceDone").onclick=game.onExit}
  function render(game){if(game.complete)return renderComplete(game);if(game.kind)return renderQuiz(game);renderHome(game)}
  function mount(options){destroy();const game={...options,kind:"",deck:[],index:0,correct:0,feedback:"",hint:false,locked:false,complete:false,gem:null};ensure(game.state);active=game;render(game)}
  function destroy(){active=null}
  window.EarthResources={mount,destroy,ensureState:ensure};
})();
